require 'async'
require 'async/queue'
require 'json'
require 'securerandom'

module MobileBackend
  module FeatureFlags
    REGISTRY = {}

    def self.enabled?(flag_name, user_context)
      flag = REGISTRY[flag_name]
      return false unless flag
      flag.evaluate(user_context)
    end

    def self.register(flag_name, &block)
      REGISTRY[flag_name] = Flag.new(flag_name, &block)
    end

    class Flag
      attr_reader :name
      def initialize(name, &evaluator)
        @name = name
        @evaluator = evaluator
      end
      def evaluate(ctx)
        @evaluator.call(ctx)
      end
    end
  end

  class NotificationDispatcher
    def initialize
      @pending_callbacks = {}
      @callback_refs = {}
      @dispatch_queue = Async::Queue.new
    end

    def register_push_callback(session_id, user_context, &callback)
      cb_id = SecureRandom.hex(8)
      entry = CallbackEntry.new(cb_id, session_id, user_context, callback)
      @pending_callbacks[cb_id] = entry
      @callback_refs[session_id] ||= []
      @callback_refs[session_id] << cb_id
      cb_id
    end

    def unregister_session(session_id)
      refs = @callback_refs.delete(session_id)
      return unless refs
      refs.each { |cb_id| @pending_callbacks.delete(cb_id) }
    end

    def dispatch_notification(notification)
      Async do |task|
        @pending_callbacks.each_pair do |cb_id, entry|
          task.async do
            process_callback_entry(entry, notification)
          end
        end
      end
    end

    def dispatch_with_batching(notifications, batch_context)
      Async do |task|
        snapshot = capture_callback_snapshot

        notifications.each_slice(10) do |batch|
          task.async do
            process_batch(snapshot, batch, batch_context)
          end
        end
      end
    end

    private

    def capture_callback_snapshot
      @pending_callbacks.dup
    end

    def process_batch(snapshot, batch, batch_context)
      batch.each do |notification|
        snapshot.each_pair do |cb_id, entry|
          next unless entry_eligible?(entry, notification)
          invoke_with_feature_check(entry, notification, batch_context)
        end
      end
    end

    def entry_eligible?(entry, notification)
      return false unless entry&.active?
      entry.user_context[:topics]&.include?(notification[:topic])
    end

    def invoke_with_feature_check(entry, notification, batch_context)
      if FeatureFlags.enabled?(:deferred_delivery, entry.user_context)
        schedule_deferred(entry, notification, batch_context)
      else
        entry.invoke(notification)
      end
    end

    def schedule_deferred(entry, notification, batch_context)
      deferred_ref = entry
      batch_context[:deferred_queue] << lambda {
        deferred_ref.invoke(notification)
      }
    end
  end

  class CallbackEntry
    attr_reader :cb_id, :session_id, :user_context

    def initialize(cb_id, session_id, user_context, callback)
      @cb_id = cb_id
      @session_id = session_id
      @user_context = user_context
      @callback = callback
      @active = true
    end

    def active?
      @active
    end

    def deactivate!
      @active = false
      @callback = nil
    end

    def invoke(notification)
      return unless @callback
      @callback.call(notification)
    end
  end

  class SessionManager
    def initialize(dispatcher)
      @dispatcher = dispatcher
      @active_sessions = {}
    end

    def create_session(user_id, device_token, topics)
      session_id = SecureRandom.uuid
      user_context = { user_id: user_id, device_token: device_token, topics: topics }
      @active_sessions[session_id] = user_context

      @dispatcher.register_push_callback(session_id, user_context) do |notification|
        deliver_push(device_token, notification)
      end

      session_id
    end

    def terminate_session(session_id)
      @active_sessions.delete(session_id)
      @dispatcher.unregister_session(session_id)
    end

    private

    def deliver_push(device_token, notification)
      # APNS/FCM delivery logic
      puts "Delivering to #{device_token}: #{notification[:body]}"
    end
  end
end

# Feature flag configuration
MobileBackend::FeatureFlags.register(:deferred_delivery) do |ctx|
  ctx[:user_id].to_i % 100 < 50
end
